export const storageKey='mengyuan-novel-flows-demo-v3';
export const clone=x=>JSON.parse(JSON.stringify(x));
export const uid=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,6)}`;
export const steps={novel:'小说写作',script:'小说转剧本',scriptReview:'小说 / 剧本质检',storyboard:'分镜生成',review:'剧本 / 分镜质检',dialogue:'台词生成',image:'参考图生成',shotPrompt:'镜头提示词',style:'风格推荐',template:'模板建立',video:'视频生成',voice:'TTS 音频生成',music:'配乐',subtitle:'字幕'};
export const defaults={novel:'根据创意 {{idea}} 和写作要求 {{instruction}}，输出适合 {{duration}} 短片的三种不同剧情方向及对应小说。',script:'将选定小说 {{novel}} 改写为 {{duration}} 短片剧本。遵循 {{instruction}}；修复时带入质检报告 {{review}}，保持人物、剧情和情绪一致。',scriptReview:'对照小说 {{novel}} 与剧本 {{script}}，检查剧情、人物情绪及剧本自身连贯性。返回简短报告与修复建议。',storyboard:'根据已确认剧本 {{script}} 拆分镜 JSON，保持稳定镜头 ID、台词、角色/场景/道具/站位、提示词及时间。',review:'对照剧本 {{script}} 和分镜 {{shots}}，检查遗漏、情绪与动作，返回 issues 和 proposedShots。',dialogue:'根据剧本 {{script}} 为镜头 {{shot}} 生成台词。',image:'结合素材描述 {{asset}} 和风格 {{style}} 生成参考图，区分角色、场景、道具、站位。',shotPrompt:'根据镜头 {{shot}}、剧本 {{script}} 和风格 {{style}} 生成提示词，保留图片引用的稳定 ID。',style:'根据剧本 {{script}} 推荐风格。',template:'将 {{style}} 整理成可复用风格模板。',video:'按镜头 {{shot}}、参考图 {{assets}} 和前镜尾帧 {{previousFrame}} 生成视频。',voice:'将台词 {{dialogue}} 按音色 {{voice}} 生成独立 TTS 音频。',music:'按剧本 {{script}} 和时长 {{duration}} 生成配乐。',subtitle:'按台词 {{dialogue}} 和时长 {{duration}} 生成字幕。'};
export function initial(){return {version:3,projectId:uid('project'),title:'未命名短片',mode:'idea',duration:60,aspect:'9:16',idea:'雨夜里，一名快递员发现收件人是十年前帮助过自己的老师。',novelInput:'',topicRequest:'',topics:[],selectedNovel:null,scriptDraft:null,scriptHistory:[],scriptReport:null,pendingScript:false,final:null,shots:[],boardVersion:0,boardScriptId:null,boardConfirmed:0,report:null,history:[],prompts:{},defaults:{...defaults},models:{},configVersion:1,styleVersion:1,styles:[{name:'现代电影',text:'写实人物，自然光影，克制表演。'},{name:'古风写意',text:'古代服饰建筑，柔和侧光，水墨质感。'},{name:'清新动画',text:'清楚轮廓，柔和色彩，细腻表情。'}],styleIndex:0,writingMethod:{mode:'skill',text:'先建立人物目标，再写冲突和转折，结尾回应开场。按目标片长限制人物、场景和事件数量。',name:'短篇叙事 skill（示例）',version:1},scriptMethod:{mode:'skill',text:'将小说改为可拍摄的分场剧本，保留人物动机和情绪转折；每场包含动作、台词和预计时长。',name:'分场剧本 skill（示例）',version:1},finishing:{voice:'温暖叙述',music:'轻钢琴',subtitles:true},jobs:[],chain:{mode:'independent',status:'idle',next:0,error:null,runId:null}};}
export function read(){try{const x=JSON.parse(localStorage.getItem(storageKey));if(x?.version===3)return x;}catch{}return initial()}
export function write(s){localStorage.setItem(storageKey,JSON.stringify(s));}
export function taskSnapshot(s,step,extra={}){return {step,configVersion:s.configVersion,model:clone(s.models[step]||{name:'演示模型'}),prompt:s.prompts[step]||s.defaults[step],method:clone(step==='novel'?s.writingMethod:step==='script'?s.scriptMethod:null),novelId:s.selectedNovel?.id||null,novelVersion:s.selectedNovel?.version||null,scriptId:s.final?.id||s.scriptDraft?.id||null,boardVersion:s.boardVersion,styleVersion:s.styleVersion,duration:s.duration,aspect:s.aspect,...clone(extra)};}
export function budget(seconds){return {min:Math.round(seconds*2),max:Math.round(seconds*4)};}
export function makeTopic(s,index,request=''){const names=['迟到的感谢','错投的秘密','最后一次派送'];const summaries=['一份普通包裹让快递员与恩师重逢，曾经没说出口的感谢终于找到归处。','收件人坚持自己没有下单，快递员查找寄件线索，揭开一场善意的隐瞒。','快递员原想完成最后一单就离开城市，却在门口收到一份改变决定的邀请。'];const i=index%3;const acts=[['门牌映入眼帘，快递员认出了老师的住处。他把车停稳，从后座取出被雨衣护住的包裹。','老师开门时没认出他。他本想放下就走，却发现老师还留着学生们写的便笺，一句感谢堵在喉咙里。','他终于叫出那声老师。老师怔了片刻，笑着递来毛巾，请他进屋。门外雨急，屋里那盏灯一直亮着。'],['老师看见包裹，摇头说自己没有买过东西。快递员核对地址，发现寄件人一栏只写着一串旧班级编号。','老师想拒收，快递员却认出包裹里是修好的旧收音机。那是全班曾用来练习朗读的机器，他决定替寄件人说完这件事。','他拨通老同学的电话，声音从收音机旁响起。老师听见熟悉的称呼，慢慢坐下，眼睛里有了笑意。'],['这是快递员离开这座城前的最后一单。他把包裹从车后取出，走上曾经熟悉的台阶，想着交付后就不再回头。','老师请他稍等，转身拿出一张社区夜校的课程表。快递员看见上面的名字，正是当年愿意为他多留一小时的老师。','老师问他愿不愿意给孩子们讲讲这些年的路。他沉默片刻，把返程车票放进口袋，说先从下周讲起。']][i];let text;if(s.duration<=30)text=[acts[0].split('。')[0]+'。',acts[1].split('。')[0]+'。',acts[2].split('。').slice(-3).join('。')].join('\n');else text=acts.map((a,j)=>a+(s.duration>=90?['雨水顺着头盔边缘滴落，街边的灯把他的影子拉得很长。他收好手机，仔细看了看门牌，才抬手敲门。','屋里传来熟悉的钟声。他抬头望向老师，想起过去那些没能认真回应的叮嘱，原本急促的动作也慢了下来。','他走出门时又回头看了一眼。那盏灯映在积水里，随着雨点轻轻晃动，他的脚步却比来时更坚定。'][j]:'')).join('\n');if(!s.idea.includes('快递'))text=`${s.idea}\n`+['主角带着明确的目标来到现场，准备完成眼前的事。','意外打断原计划。'+(i===0?'一个熟悉的人出现，迫使主角面对旧日心结。':i===1?'一条被忽略的线索改变了主角对事情的判断。':'一次看似平常的邀请，让主角重新考虑离开的决定。'),'主角改变行动，回应了开场的问题，也为这段经历留下新的意义。'].join('\n');const b=budget(s.duration);if(text.length>b.max)text=text.slice(0,b.max-1)+'。';return {id:uid('topic'),title:request?`新选题 · ${request.slice(0,12)}`:s.idea.includes('快递')?names[i]:['重逢与选择','被遗漏的线索','一次新的邀请'][i],logline:request?`围绕“${request}”展开的新剧情方向。`:s.idea.includes('快递')?summaries[i]:['熟悉的人突然出现，主角必须面对旧日心结并作出选择。','被忽略的线索推翻最初判断，主角重新理解眼前的故事。','一次普通邀请打断离开计划，主角为新的可能留下来。'][i],direction:i,text,version:1,messages:[],versions:[],snapshot:taskSnapshot(s,'novel',{idea:s.idea,request}),targetDuration:s.duration,aspect:s.aspect,selected:false};}
export function selectNovel(s,topic){if(!topic.text.trim())throw Error('小说内容不能为空');s.selectedNovel={id:topic.id,title:topic.title,text:topic.text,version:topic.version||1,targetDuration:s.duration};s.title=topic.title;s.final=null;s.scriptReport=null;s.boardConfirmed=0;s.report=null;s.pendingScript=true;}
export function scriptText(s,repaired=false){const parts=s.selectedNovel.text.split(/\n+/).filter(Boolean);const each=Math.round(s.duration/3);return ['开场','发展','收束'].map((name,i)=>`【${name} ${i*each}–${i===2?s.duration:(i+1)*each}秒】\n${parts[i]||parts[parts.length-1]}\n情绪：${i===1&&!repaired?'轻松调侃（待检查示例）':i===1?'迟疑转为真诚':'克制、自然'}。`).join('\n\n');}
export function buildScript(s,repair=false){if(!s.selectedNovel)throw Error('尚未选定小说');if(s.scriptDraft)s.scriptHistory.push(clone(s.scriptDraft));const report=repair?clone(s.scriptReport):null;s.scriptDraft={id:uid('script'),text:repair&&s.scriptDraft?s.scriptDraft.text.replaceAll('轻松调侃（待检查示例）','迟疑转为真诚'):scriptText(s,repair),version:(s.scriptDraft?.version||0)+1,novelId:s.selectedNovel.id,novelVersion:s.selectedNovel.version,needsRepair:!repair,snapshot:taskSnapshot(s,'script',{sourceText:s.selectedNovel.text,reviewContext:report})};s.scriptReport=null;s.final=null;s.boardConfirmed=0;s.pendingScript=false;return s.scriptDraft;}
export function reviewScript(s){const d=s.scriptDraft;if(!d||d.novelId!==s.selectedNovel?.id||d.novelVersion!==s.selectedNovel?.version)throw Error('小说来源已变化，请重新生成剧本');s.scriptReport={id:uid('sqc'),scriptId:d.id,version:d.version,novelId:d.novelId,novelVersion:d.novelVersion,issues:d.needsRepair?[{type:'人物情绪',text:'发展段被标成轻松调侃，建议恢复小说中的迟疑与真诚，并补足转折。',evidence:s.selectedNovel.text.split('\n')[1]||s.selectedNovel.text}]:[],summary:d.needsRepair?'1 项示例问题：人物情绪需要修复。':'示例复检完成，未返回待处理问题。',snapshot:taskSnapshot(s,'scriptReview')};return s.scriptReport;}
export function scriptReady(s){return !!s.scriptDraft&&s.scriptDraft.snapshot.duration===s.duration&&s.scriptDraft.snapshot.aspect===s.aspect&&!!s.scriptReport&&s.scriptReport.scriptId===s.scriptDraft.id&&s.scriptReport.version===s.scriptDraft.version&&!s.scriptReport.issues.length&&s.scriptDraft.novelId===s.selectedNovel?.id&&s.scriptDraft.novelVersion===s.selectedNovel?.version;}
export function confirmScript(s){if(!scriptReady(s))throw Error('请完成当前剧本质检与修复');s.final=clone(s.scriptDraft);s.boardConfirmed=0;}
export function selectFinal(s,c){s.final=clone(c);s.boardConfirmed=0;s.report=null;}
export function boardStale(s){return !!s.shots.length&&(!s.final||s.boardScriptId!==s.final.id);}
export function changed(s,index=0){s.boardVersion++;s.boardConfirmed=0;s.report=null;invalidateChain(s,index);}
export function invalidateChain(s,index){for(let i=index;i<s.shots.length;i++){const sh=s.shots[i];if(i===index||sh.video?.mode==='sequential'){sh.videoStale=!!sh.video;if(i>index)sh.previousFrameStale=!!sh.previousFrame;}}if(s.chain.status!=='idle'){s.chain.status='interrupted';s.chain.message='输入已变化，请完成检查后重新生成受影响镜头。';}s.chain.runId=null;}
export const refs=prompt=>[...prompt.matchAll(/@\[([^\]]+)\]/g)].map(m=>m[1]);
export function validateRefs(sh){const ids=refs(sh.prompt);const assets=new Map(sh.assets.map(a=>[a.id,a]));return ids.map(id=>assets.has(id)?(!assets.get(id).image?`参考图尚未生成：${assets.get(id).name}`:null):`未知图片引用：${id}`).filter(Boolean);}
export function makeShots(s){if(!s.final)throw Error('请先确认剧本');const parts=s.final.text.split(/\n\n/).filter(Boolean);return [0,1,2].map(i=>{const id=uid('shot');const assets=['角色','场景','道具','站位'].map((kind,j)=>({id:`${id}-asset-${j+1}`,kind,name:['主角','故事场景','关键道具','人物站位'][j],description:['保持同一人物外观','保持同一空间与光线','匹配剧情中的关键物件','标注人物左右关系、距离、朝向与视线'][j],image:null,confirmed:false,version:1}));return {id,dialogue:['这里，我好像来过。','这件事，我一直记得。','谢谢你愿意留下来。'][i],speaker:'主角',emotion:'克制',duration:i===2?s.duration-2*Math.round(s.duration/3):Math.round(s.duration/3),prompt:(parts[i]||s.final.text)+(i===1?'\n直接递交物件（待补充取件动作示例）。':'')+'\n参考：'+assets.map(a=>`@[${a.id}]`).join(' '),assets,version:1,video:null,videoStale:false,audio:null,previousFrame:null,previousFrameStale:false};});}
export function boardReview(s){if(boardStale(s))throw Error('剧本版本已变化');const issues=s.shots.filter(sh=>sh.prompt.includes('待补充取件动作示例')).map(sh=>({shotId:sh.id,type:'动作连贯性',evidence:'镜头直接递交物件，需要检查并补齐前置动作。',before:sh.prompt,after:sh.prompt.replace('直接递交物件（待补充取件动作示例）。','先取出物件，走到对方面前，再双手递交；保持朝向与人物情绪连贯。')}));s.report={schemaVersion:1,scriptId:s.final.id,baseBoardVersion:s.boardVersion,issues,proposedShots:s.shots.map(sh=>({id:sh.id,prompt:issues.find(x=>x.shotId===sh.id)?.after||sh.prompt,dialogue:sh.dialogue})),snapshot:taskSnapshot(s,'review')};return s.report;}
export function validateReport(r,s){if(!r||r.schemaVersion!==1||r.scriptId!==s.final?.id||r.baseBoardVersion!==s.boardVersion||boardStale(s))throw Error('报告已过期，请重新质检');if(!Array.isArray(r.proposedShots)||!Array.isArray(r.issues)||r.proposedShots.length!==s.shots.length)throw Error('报告结构错误');const ids=new Set();for(const p of r.proposedShots){const sh=s.shots.find(x=>x.id===p.id);if(!sh||ids.has(p.id)||typeof p.prompt!=='string'||typeof p.dialogue!=='string'||!p.prompt.trim()||refs(p.prompt).some(id=>!sh.assets.some(a=>a.id===id)))throw Error('建议版含重复镜头、非法字段或未知图片引用');ids.add(p.id);}return true;}
export function applyReport(s){validateReport(s.report,s);if(!s.report.issues.length)throw Error('没有待采用建议');s.history.push({boardVersion:s.boardVersion,scriptId:s.boardScriptId,shots:clone(s.shots)});const r=clone(s.report);for(const p of r.proposedShots){const i=s.shots.findIndex(sh=>sh.id===p.id),sh=s.shots[i];if(sh.prompt!==p.prompt||sh.dialogue!==p.dialogue){sh.prompt=p.prompt;sh.dialogue=p.dialogue;sh.version++;sh.assets.forEach(a=>a.confirmed=false);invalidateChain(s,i);}}s.boardVersion++;s.boardConfirmed=0;s.report=null;}
export function generationReady(s){return !!s.shots.length&&!boardStale(s)&&s.boardConfirmed===s.boardVersion&&s.shots.every(sh=>!validateRefs(sh).length&&sh.assets.every(a=>a.image&&a.confirmed));}
export function makeVideoSnapshot(s,sh,mode,previous){if(mode==='sequential'&&previous&&(!previous.video||previous.videoStale||!previous.video.lastFrame))throw Error('前镜视频或尾帧无效，顺序任务暂停');return {...taskSnapshot(s,'video'),shotId:sh.id,shotVersion:sh.version,assetVersions:sh.assets.map(a=>({id:a.id,version:a.version})),referencedIds:refs(sh.prompt),mode,previousVideoId:previous?.video?.id||null,previousFrame:previous?.video?.lastFrame||null};}
